BOOL __stdcall MouseIsInRange(int32_t nSizeX, int32_t nSizeY, int32_t nX, int32_t nY) {
    int nMouseX = ui::GetMouseX();
    int nMouseY = ui::GetMouseY();
    if (!(nX <= nMouseX && nMouseX <= nX + nSizeX && nY - nSizeY <= nMouseY && nMouseY <= nY)) {
      return 0;
    }

    return 1;
}

