void __stdcall HELP_DrawHelpButton() {
    D2GfxDataStrc sGfxData;
    BOOL bUIFlag = ui::GetUIFlag(UI_SKILLTREE);
    if (!bUIFlag) {
      int32_t nSeenHelp;
      bUIFlag = ui::GetUIFlag(UI_SKILLSELECT);
      if (!bUIFlag) {
        bUIFlag = ui::GetUIFlag(UI_INVENTORY);
        if (!bUIFlag) {
          bUIFlag = ui::GetUIFlag(UI_NPCSHOP);
          if (!bUIFlag) {
            bUIFlag = ui::GetUIFlag(UI_MPTRADE);
            if (!bUIFlag) {
              gpHelpScrollButtonUp = ui::GetUIFlag(UI_STASH);
              if (!gpHelpScrollButtonUp) {
                nSeenHelp = GetSeenHelpMenuValue();
                if (!nSeenHelp) {
                  memset(&sGfxData, 0, 0x48);
                  HELP_DrawHelpButtonTooltip();
                  sGfxData.pDC6 = gpUIStatLevelUpButtonImages;
                  sGfxData.nDirection = 0;
                  sGfxData.nFrameNumber = 0;
                  D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, ScreenSizeX - 0x4b, ScreenSizeY - 0xa0, -1, DRAW_SOLID, nullptr);
                  sGfxData.nFrameNumber = (int)(gpHelpScrollButtonDown != 0);
                  sGfxData.pDC6 = gpUIStatLevelUpPanelImages;
                  D2gfx::D2GFX::D2GFX_DrawImage(&sGfxData, ScreenSizeX - 0x48, ScreenSizeY - 0xa4, -1, DRAW_SOLID, nullptr);
                  return;
                }

                Draw::SetUIFlag(UI_HELPSCREENBTN, UI_RESET, 0);
                return;
              }
            }
          }
        }
      }
    }

    gpHelpScrollButtonUp = 1;
}

void __stdcall INPUT_HelpScrollButtonDown(D2UIMouseMsgStrc * pMsg) {
    int nScreenY = ScreenSizeY;
    int nScreenX = ScreenSizeX;
    if (gpHelpScrollButtonUp) {
      return;
    }

    int nBottomY = ScreenSizeY - 0xa0;
    int nLeftX = ScreenSizeX - 0x4b;
    int nMouseX = ui::GetMouseX();
    int nMouseY = ui::GetMouseY();
    if (!(nLeftX <= nMouseX && nMouseX <= nScreenX - 0x28 && nScreenY - 0xc4 <= nMouseY && nMouseY <= nBottomY)) {
      return;
    }

    gpHelpScrollButtonDown = 1;
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
}

void __stdcall INPUT_HelpScrollButtonUp(D2UIMouseMsgStrc * pMsg) {
    int nScreenY = ScreenSizeY;
    int nScreenX = ScreenSizeX;
    if (gpHelpScrollButtonUp) {
      return;
    }

    int nBottomY = ScreenSizeY - 0xa0;
    int nLeftX = ScreenSizeX - 0x4b;
    int nMouseX = ui::GetMouseX();
    int nMouseY = ui::GetMouseY();
    if (!(nLeftX <= nMouseX && nMouseX <= nScreenX - 0x28 && nScreenY - 0xc4 <= nMouseY && nMouseY <= nBottomY)) {
      return;
    }

    Draw::SetUIFlag(UI_HELPSCREENBTN, UI_RESET, 0);
    Draw::SetUIFlag(UI_HELPSCREEN, UI_TOGGLE, 0);
    bSeenHelpMenu = 1;
    Storm::Source::SReg::SRegSaveValue("Diablo II", "Help Menu", 1, 1);
    gpHelpScrollButtonDown = 0;
    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
}

